27	const REGISTRY_KEY = Symbol.for("@ts-drp/storage/ahe-reclamation-maintenance-v1");
28	type Backend = "browser" | "sqlite";
29	type AheReclamationMaintenance = NonNullable<ReturnType<typeof resolveNodeAheReclamationMaintenance>>;
30	type Neutral = {
31		bindAheReclamationMaintenance(store: AheDurableStore, maintenance: AheReclamationMaintenance): boolean;
32		aheReclamationMaintenanceForStore(store: AheDurableStore): AheReclamationMaintenance | undefined;
