62			if (legacy === undefined) throw new Error("GENUINE_BACKEND_PREMISE_MISSING");
63			expect(await store.readHead(D109C_OBJECT)).toEqual({ ok: true, value: { kind: "none", objectId: D109C_OBJECT } });
