134	function statementName(node: ts.Statement, file: ts.SourceFile): string | undefined {
135		if (ts.isVariableStatement(node)) return node.declarationList.declarations[0]?.name.getText(file);
136		if (
137			ts.isFunctionDeclaration(node) ||
138			ts.isClassDeclaration(node) ||
139			ts.isTypeAliasDeclaration(node) ||
140			ts.isInterfaceDeclaration(node)
141		)
142			return node.name?.text;
143		return undefined;
144	}
