153				(node) => ts.isFunctionDeclaration(node) && node.name?.text === registerName
154			);
155			expect(registration).toBeDefined();
156			if (registration === undefined) throw new Error("REGISTRATION_SOURCE_PREMISE_MISSING");
157			const calls: string[] = [];
158			const visit = (node: ts.Node): void => {
159				if (ts.isCallExpression(node) || ts.isNewExpression(node)) calls.push(node.expression.getText(file));
160				ts.forEachChild(node, visit);
161			};
162			visit(registration);
163			expect(calls.filter((name) => name === className)).toHaveLength(1);
