469	/**
470	 * Produces the one pure deletion decision consumed inside native transactions.
471	 * @param request - Untrusted D.109a AHE subset.
472	 * @param snapshot - Complete decoded generation/promotion scan plus required blob observations.
473	 * @returns Frozen floor rewrite and exact physical deletion set.
474	 */
475	export function classifyAheReclamation(request: unknown, snapshot: AheReclamationSnapshot): AheReclamationDecision {
476		const input = captureAheReclamationInput(request);
477		try {
478			if (!isClosedRecord(snapshot, ["blobs", "generations", "head", "promotions"])) {
479				corrupt("native snapshot was not one exact record");
480			}
481			const head = copyExpectedHead(snapshot.head, input.objectId);
482			if (head === undefined) corrupt("native head was malformed or cross-object");
483			if (!headsEqual(head, input.expectedHead)) retry("head changed before reclamation");
484			const generations = copyGenerations(snapshot.generations);
485			const promotions = copyPromotions(snapshot.promotions);
486			const blobs = copyBlobFacts(snapshot.blobs);
487			verifyPromotionsAndBlobs(generations, promotions, blobs);
488	
489			const target = generations.filter(({ objectId }) => objectId === input.objectId);
490			const byId = new Map(target.map((generation) => [generation.generationId, generation]));
491			const active = byId.get(input.activeGenerationId);
492			if (
493				active === undefined ||
494				active.state !== "Adopted" ||
495				active.closureDigest !== input.expectedHead.closureDigest
496			) {
497				corrupt("active head did not bind one adopted generation");
498			}
499			const firstId = input.rollbackGenerationIds[0];
500			const floorId = input.rollbackGenerationIds[1];
501			if (active.baseExpectedHead.kind !== "present") corrupt("active generation did not retain a rollback parent");
502			const first = byId.get(active.baseExpectedHead.generationId);
503			if (first === undefined || first.baseExpectedHead.kind !== "present") {
504				corrupt("retained rollback lineage contained a gap");
505			}
506			const floor = byId.get(first.baseExpectedHead.generationId);
507			if (floor === undefined) corrupt("retained rollback lineage contained a gap");
508			if (first.generationId !== firstId || floor.generationId !== floorId) {
509				retry("planned rollback generations changed before reclamation");
510			}
511			if (
512				first.state !== "Superseded" ||
513				floor.state !== "Superseded" ||
514				!parentMatches(active, first, input.expectedHead.revision) ||
515				!parentMatches(first, floor, active.baseExpectedHead.revision)
516			) {
517				corrupt("retained rollback lineage was invalid");
518			}
519	
520			const retained = new Set([active.generationId, first.generationId, floor.generationId]);
521			const selected: GenerationRecord[] = [];
522			let replay = false;
523			let normalizedThisCall = false;
524			if (headsEqual(floor.baseExpectedHead, input.lineageFloor.expectedBaseExpectedHead)) {
525				normalizedThisCall = !headsEqual(
526					input.lineageFloor.expectedBaseExpectedHead,
527					input.lineageFloor.replacementBaseExpectedHead
528				);
529				let cursor = floor.baseExpectedHead;
530				let expectedRevision = first.baseExpectedHead.kind === "present" ? first.baseExpectedHead.revision : 0;
531				const visited = new Set<GenerationId>();
532				while (cursor.kind === "present") {
533					if (visited.has(cursor.generationId)) corrupt("reclamation prefix contained a cycle");
534					const generation = byId.get(cursor.generationId);
535					if (
536						generation === undefined ||
537						generation.state !== "Superseded" ||
538						cursor.objectId !== input.objectId ||
539						cursor.closureDigest !== generation.closureDigest ||
540						cursor.revision !== expectedRevision - 1
541					) {
542						corrupt("reclamation prefix contained a gap or invalid parent");
543					}
544					visited.add(generation.generationId);
545					selected.push(generation);
546					expectedRevision = cursor.revision;
547					cursor = generation.baseExpectedHead;
548				}
549				if (cursor.objectId !== input.objectId) corrupt("reclamation prefix terminated in another object");
550			} else if (headsEqual(floor.baseExpectedHead, input.lineageFloor.replacementBaseExpectedHead)) {
551				replay = true;
552				if (input.lineageFloor.deleteGenerationIds.some((generationId) => byId.has(generationId))) {
553					corrupt("normalized floor retained part of the requested prefix");
554				}
555			} else {
556				retry("lineage floor changed before reclamation");
557			}
558	
559			const selectedIds = selected.map(({ generationId }) => generationId).sort();
560			if (!replay && !sameIds(selectedIds, input.lineageFloor.deleteGenerationIds)) {
561				retry("requested generation prefix no longer matches the complete lineage");
562			}
563			const extras = target.filter(
564				({ generationId }) => !retained.has(generationId) && !selectedIds.includes(generationId)
565			);
566			if (extras.length !== 0) {
567				const requestedPrefix = new Set(input.lineageFloor.deleteGenerationIds);
568				if (
569					replay &&
570					extras.some(
571						({ baseExpectedHead }) =>
572							baseExpectedHead.kind === "present" && requestedPrefix.has(baseExpectedHead.generationId)
573					)
574				) {
575					corrupt("normalized replay retained a dangling parent into the reclaimed prefix");
576				}
577				retry("target generation set changed before reclamation");
578			}
579	
580			const selectedSet = new Set(selectedIds);
581			const deletePromotions = promotions.filter(
582				({ generationId, objectId }) => objectId === input.objectId && selectedSet.has(generationId)
583			);
584			const candidateDigests = new Set(deletePromotions.map(({ digest }) => digest));
585			const remainingGenerationReferences = new Set(
586				generations
587					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
588					.flatMap(({ closure }) => closure.map(({ digest }) => digest))
589			);
590			const remainingPromotionReferences = new Set(
591				promotions
592					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
593					.map(({ digest }) => digest)
594			);
595			const deleteBlobDigests = [...candidateDigests]
596				.filter((digest) => !remainingGenerationReferences.has(digest) && !remainingPromotionReferences.has(digest))
597				.sort();
598			const rewrittenGeneration = cloneGeneration({
599				...floor,
600				baseExpectedHead: input.lineageFloor.replacementBaseExpectedHead,
601			});
602			return Object.freeze({
603				deleteBlobDigests: Object.freeze(deleteBlobDigests),
604				deleteGenerationIds: Object.freeze(normalizedThisCall ? selectedIds : []),
605				deletePromotions: Object.freeze(normalizedThisCall ? deletePromotions : []),
606				floor: Object.freeze({
607					generation: cloneGeneration(floor),
608					normalizedThisCall,
609					rewrittenGeneration,
610				}),
611				input,
612			});
613		} catch (error) {
614			if (error instanceof AheReclamationError) throw error;
615			throw failure("AHE_RECLAMATION_CORRUPT", "native snapshot could not be inspected", error);
616		}
617	}
618	
619	/**
620	 * Constructs the detached immutable receipt after exact native row counts pass.
621	 * @param decision - Shared classifier decision used by the transaction.
622	 * @returns Frozen receipt containing actual writes for this call.
623	 */
624	export function createAheReclamationReceipt(decision: AheReclamationDecision): AheReclamationReceipt {
625		const { input } = decision;
626		return Object.freeze({
627			activeGenerationId: input.activeGenerationId,
628			availabilityPolicyDigest: input.availabilityPolicyDigest,
629			closedEpoch: input.closedEpoch,
630			deletedBlobDigests: Object.freeze([...decision.deleteBlobDigests]),
631			deletedGenerationIds: Object.freeze([...decision.deleteGenerationIds]),
632			deletedPromotionCount: decision.deletePromotions.length,
633			expectedHead: cloneHead(input.expectedHead) as PresentHead,
634			floor: Object.freeze({
635				expectedFormerBaseExpectedHead: cloneHead(input.lineageFloor.expectedBaseExpectedHead),
636				generationId: input.lineageFloor.generationId,
637				normalizedThisCall: decision.floor.normalizedThisCall,
638				replacementBaseExpectedHead: cloneHead(input.lineageFloor.replacementBaseExpectedHead) as Readonly<{
639					kind: "none";
640					objectId: StorageObjectId;
641				}>,
642			}),
643			objectId: input.objectId,
644			reclaimedGenerationIds: Object.freeze([...input.lineageFloor.deleteGenerationIds]),
645			rollbackGenerationIds: Object.freeze([...input.rollbackGenerationIds]) as readonly [GenerationId, GenerationId],
646		});
647	}
648	
649	/**
650	 * Creates one frozen lifecycle or substrate error without widening the code set.
651	 * @param code - Closed error code.
652	 * @param message - Diagnostic summary.
653	 * @param cause - Optional substrate cause.
654	 * @returns Frozen classified error.
655	 */
656	export function createAheReclamationError(
657		code: AheReclamationErrorCode,
658		message: string,
659		cause?: unknown
660	): AheReclamationError {
661		return failure(code, message, cause);
662	}
663

