10	import {
11		AheReclamationError,
12		type AheReclamationMaintenance,
13		type AheReclamationPromotion,
14		type AheReclamationReceipt,
15		type AheReclamationSnapshot,
16		bindAheReclamationMaintenance,
17		captureAheReclamationInput,
18		classifyAheReclamation,
19		createAheReclamationError,
20		createAheReclamationReceipt,
21	} from "@ts-drp/storage/maintenance";
22	
23	import { runInternalPrimaryDispatch } from "./primary-dispatch.js";
24	import {
25		PHASE_2D_BLOBS_STORE,
26		PHASE_2D_GENERATIONS_STORE,
27		PHASE_2D_OBJECTS_STORE,
28		PHASE_2D_PROMOTIONS_STORE,
29	} from "./schema-idb.js";
30	
31	export type BrowserAheReclamationCrashEdge =
32		| "after-floor-rewrite"
33		| "after-promotion-delete"
34		| "after-generation-delete"
35		| "after-blob-delete"
36		| "before-commit"
37		| "after-commit";
38	
39	export type BrowserAheReclamationCrashObserver = (
40		edge: BrowserAheReclamationCrashEdge,
41		transaction: IDBTransaction
42	) => void;
43	
44	export type BrowserAheReclamationCountFault =
45		| "blob delete"
46		| "floor rewrite"
47		| "generation delete"
48		| "promotion delete";
49	
50	export type BrowserAheReclamationLifecycle = Readonly<{
51		acquireRecoveryTurn(): (() => void) | Promise<() => void>;
52		finishOperation(): void;
53		isClosed(): boolean;
54		isPoisoned(): boolean;
55		latchPoison(reason: "NON_CANONICAL_RECORD"): unknown;
56		startOperation(): IDBDatabase | undefined;
57	}>;
58	
59	type TransactionOutcome = Readonly<{ ok: true }> | Readonly<{ cause: unknown; ok: false }>;
60	
61	const maintenanceByStore = new WeakMap<AheDurableStore, AheReclamationMaintenance>();
62	const crashObserverByStore = new WeakMap<AheDurableStore, BrowserAheReclamationCrashObserver>();
63	const countFaultByStore = new WeakMap<AheDurableStore, BrowserAheReclamationCountFault>();
64	
65	function rowProperty(value: unknown, key: string): unknown {
66		if (typeof value !== "object" || value === null) return undefined;
67		const descriptor = Object.getOwnPropertyDescriptor(value, key);
68		return descriptor !== undefined && "value" in descriptor ? descriptor.value : undefined;
69	}
70	
71	function bytes(value: unknown): Uint8Array {
72		if (!(value instanceof Uint8Array)) throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "row bytes invalid");
73		return new Uint8Array(value);
74	}
75	
76	function requestValue<T>(request: IDBRequest<T>): Promise<T> {
77		return new Promise((resolve, reject) => {
78			request.addEventListener("success", () => resolve(request.result), { once: true });
79			request.addEventListener("error", () => reject(request.error ?? new Error("IndexedDB request failed")), {
80				once: true,
81			});
82		});
83	}
84	
85	function transactionOutcome(transaction: IDBTransaction): Promise<TransactionOutcome> {
86		return new Promise((resolve) => {
87			let observedError: unknown;
88			transaction.addEventListener("complete", () => resolve({ ok: true }), { once: true });
89			transaction.addEventListener(
90				"abort",
91				() => resolve({ cause: transaction.error ?? observedError ?? new Error("transaction aborted"), ok: false }),
92				{ once: true }
93			);
94			transaction.addEventListener(
95				"error",
96				() => {
97					observedError ??= transaction.error ?? new Error("transaction failed");
98				},
99				{ once: true }
100			);
101		});
102	}
103	
104	function abortIfActive(transaction: IDBTransaction): void {
105		try {
106			transaction.abort();
107		} catch {
108			// Preserve the primary classified failure.
109		}
110	}
111	
112	async function expectKey(
113		store: AheDurableStore,
114		objectStore: IDBObjectStore,
115		key: IDBValidKey,
116		expected: "absent" | "present",
117		label: BrowserAheReclamationCountFault
118	): Promise<void> {
119		const value = await requestValue(objectStore.getKey(key));
120		const matches = expected === "present" ? value !== undefined : value === undefined;
121		if (!matches || countFaultByStore.get(store) === label) {
122			throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", `${label} count mismatch`);
123		}
124	}
125	
126	async function loadSnapshot(transaction: IDBTransaction, objectId: string): Promise<AheReclamationSnapshot> {
127		const parsedObjectId = parseStorageObjectId(objectId);
128		if (!parsedObjectId.ok) throw createAheReclamationError("AHE_RECLAMATION_INVALID_ARGUMENT", "object ID invalid");
129		const objectRow = await requestValue(transaction.objectStore(PHASE_2D_OBJECTS_STORE).get(objectId));
130		let head: ExpectedHead = { kind: "none", objectId: parsedObjectId.value };
131		const headRecord = rowProperty(objectRow, "record");
132		if (objectRow !== undefined && headRecord !== null && headRecord !== undefined) {
133			const decoded = decodeHeadRecordV1(bytes(headRecord));
134			if (!decoded.ok || decoded.value.objectId !== objectId) {
135				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "head row was malformed or misbound");
136			}
137			head = decoded.value;
138		}
139	
140		const generationRows = await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).getAll());
141		const generations: GenerationRecord[] = [];
142		for (const row of generationRows) {
143			const decoded = decodeGenerationRecordV1(bytes(rowProperty(row, "record")));
144			if (
145				!decoded.ok ||
146				decoded.value.objectId !== rowProperty(row, "objectId") ||
147				decoded.value.generationId !== rowProperty(row, "generationId")
148			) {
149				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "generation row was malformed or misbound");
150			}
151			generations.push(decoded.value);
152		}
153	
154		const promotionRows = await requestValue(transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).getAll());
155		const promotions = promotionRows.map(
156			(row) =>
157				({
158					digest: rowProperty(row, "digest"),
159					generationId: rowProperty(row, "generationId"),
160					objectId: rowProperty(row, "objectId"),
161				}) as AheReclamationPromotion
162		);
163		const digests = [...new Set(promotions.map(({ digest }) => digest))];
164		const blobStore = transaction.objectStore(PHASE_2D_BLOBS_STORE);
165		const blobs = [];
166		for (const digest of digests) {
167			const row = await requestValue(blobStore.get(digest));
168			if (row !== undefined) blobs.push({ bytes: bytes(rowProperty(row, "bytes")), digest });
169		}
170		return { blobs, generations, head, promotions } as AheReclamationSnapshot;
171	}
172	
173	class BrowserAheReclamationMaintenance implements AheReclamationMaintenance {
174		public constructor(
175			private readonly store: AheDurableStore,
176			private readonly lifecycle: BrowserAheReclamationLifecycle,
177			private readonly databaseName: string
178		) {}
179	
180		public async reclaimClosedEpoch(input: unknown): Promise<AheReclamationReceipt> {
181			const captured = captureAheReclamationInput(input);
182			return runInternalPrimaryDispatch({
183				databaseName: this.databaseName,
184				identity: "ahe-reclamation:v1",
185				task: () => this.reclaimCaptured(captured),
186			});
187		}
188	
189		private async reclaimCaptured(
190			captured: ReturnType<typeof captureAheReclamationInput>
191		): Promise<AheReclamationReceipt> {
192			const database = this.lifecycle.startOperation();
193			if (database === undefined) {
194				throw createAheReclamationError("AHE_RECLAMATION_STORE_CLOSED", "store is closed");
195			}
196			const turn = this.lifecycle.acquireRecoveryTurn();
197			const release = typeof turn === "function" ? turn : await turn;
198			let transaction: IDBTransaction | undefined;
199			let completion: Promise<TransactionOutcome> | undefined;
200			let committed = false;
201			try {
202				if (this.lifecycle.isClosed()) {
203					throw createAheReclamationError("AHE_RECLAMATION_STORE_CLOSED", "store closed before reclamation");
204				}
205				if (this.lifecycle.isPoisoned()) {
206					throw createAheReclamationError("AHE_RECLAMATION_STORE_POISONED", "store is poisoned");
207				}
208				transaction = database.transaction(
209					[PHASE_2D_BLOBS_STORE, PHASE_2D_GENERATIONS_STORE, PHASE_2D_OBJECTS_STORE, PHASE_2D_PROMOTIONS_STORE],
210					"readwrite",
211					{ durability: "strict" }
212				);
213				completion = transactionOutcome(transaction);
214				if (transaction.durability !== "strict") {
215					throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "strict durability unavailable");
216				}
217				const decision = classifyAheReclamation(captured, await loadSnapshot(transaction, captured.objectId));
218				const observer = crashObserverByStore.get(this.store);
219				if (decision.floor.normalizedThisCall) {
220					const generationStore = transaction.objectStore(PHASE_2D_GENERATIONS_STORE);
221					const floorKey = [captured.objectId, captured.lineageFloor.generationId];
222					await expectKey(this.store, generationStore, floorKey, "present", "floor rewrite");
223					await requestValue(
224						generationStore.put({
225							generationId: captured.lineageFloor.generationId,
226							objectId: captured.objectId,
227							record: encodeGenerationRecordV1(decision.floor.rewrittenGeneration),
228						})
229					);
230					await expectKey(this.store, generationStore, floorKey, "present", "floor rewrite");
231					observer?.("after-floor-rewrite", transaction);
232				}
233				const promotionStore = transaction.objectStore(PHASE_2D_PROMOTIONS_STORE);
234				for (const promotion of decision.deletePromotions) {
235					const key = [promotion.objectId, promotion.generationId, promotion.digest];
236					await expectKey(this.store, promotionStore, key, "present", "promotion delete");
237					await requestValue(promotionStore.delete(key));
238					await expectKey(this.store, promotionStore, key, "absent", "promotion delete");
239				}
240				if (decision.floor.normalizedThisCall) observer?.("after-promotion-delete", transaction);
241				const generationStore = transaction.objectStore(PHASE_2D_GENERATIONS_STORE);
242				for (const generationId of decision.deleteGenerationIds) {
243					const key = [captured.objectId, generationId];
244					await expectKey(this.store, generationStore, key, "present", "generation delete");
245					await requestValue(generationStore.delete(key));
246					await expectKey(this.store, generationStore, key, "absent", "generation delete");
247				}
248				if (decision.floor.normalizedThisCall) observer?.("after-generation-delete", transaction);
249				const blobStore = transaction.objectStore(PHASE_2D_BLOBS_STORE);
250				for (const digest of decision.deleteBlobDigests) {
251					await expectKey(this.store, blobStore, digest, "present", "blob delete");
252					await requestValue(blobStore.delete(digest));
253					await expectKey(this.store, blobStore, digest, "absent", "blob delete");
254				}
255				if (decision.floor.normalizedThisCall) observer?.("after-blob-delete", transaction);
256	
257				const post = classifyAheReclamation(captured, await loadSnapshot(transaction, captured.objectId));
258				if (
259					post.floor.normalizedThisCall ||
260					post.deleteGenerationIds.length !== 0 ||
261					post.deletePromotions.length !== 0 ||
262					post.deleteBlobDigests.length !== 0
263				) {
264					throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "post-state was not a complete replay");
265				}
266				observer?.("before-commit", transaction);
267				transaction.commit();
268				const outcome = await completion;
269				if (!outcome.ok) throw outcome.cause;
270				committed = true;
271				observer?.("after-commit", transaction);
272				return createAheReclamationReceipt(decision);
273			} catch (error) {
274				if (!committed && transaction !== undefined) abortIfActive(transaction);
275				if (!committed && completion !== undefined) await completion;
276				if (error instanceof AheReclamationError) {
277					if (error.code === "AHE_RECLAMATION_CORRUPT") this.lifecycle.latchPoison("NON_CANONICAL_RECORD");
278					throw error;
279				}
280				throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "IndexedDB reclamation failed", error);
281			} finally {
282				release();
283				this.lifecycle.finishOperation();
284			}
285		}
286	}
287	
288	/**
289	 * Registers maintenance authority for one genuine IndexedDB facade.
290	 * @param store - Exact facade identity.
291	 * @param lifecycle - Owning facade lifecycle controls.
292	 * @param databaseName - Exact adapter-owned database identity.
293	 */
294	export function registerBrowserAheReclamationMaintenance(
295		store: AheDurableStore,
296		lifecycle: BrowserAheReclamationLifecycle,
297		databaseName: string
298	): void {
299		const maintenance = new BrowserAheReclamationMaintenance(store, lifecycle, databaseName);
300		if (!bindAheReclamationMaintenance(store, maintenance)) {
301			throw new TypeError("AHE maintenance facade is already registered");
302		}
303		maintenanceByStore.set(store, maintenance);
304	}
305	
306	/**
307	 * Resolves maintenance only for the registered facade identity.
308	 * @param store - Candidate facade identity.
309	 * @returns The identity-bound maintenance owner, if registered.
310	 */
311	export function browserAheReclamationMaintenanceForStore(
312		store: AheDurableStore
313	): AheReclamationMaintenance | undefined {
314		return maintenanceByStore.get(store);
315	}
316	
317	/**
318	 * Installs the maintenance-only worker-termination observer for a package-local test.
319	 * @param store - Exact registered IndexedDB facade.
320	 * @param observer - Fixed checkpoint observer.
321	 */
322	export function installBrowserAheReclamationCrashObserver(
323		store: AheDurableStore,
324		observer: BrowserAheReclamationCrashObserver
325	): void {
326		if (!maintenanceByStore.has(store)) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
327		crashObserverByStore.set(store, observer);
328	}
329	
330	/**
331	 * Installs one fixed maintenance-only count mismatch for a package-local browser test.
332	 * @param store - Exact registered IndexedDB facade.
333	 * @param fault - Fixed row-count category to misreport.
334	 */
335	export function installBrowserAheReclamationCountFault(
336		store: AheDurableStore,
337		fault: BrowserAheReclamationCountFault
338	): void {
339		if (!maintenanceByStore.has(store)) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
340		countFaultByStore.set(store, fault);
341	}
