104	class IdbAdapterLifecycle {
105		private activeOperations = 0;
106		private closePromise: Promise<void> | undefined;
107		private connection: IDBDatabase | undefined;
108		private poisoned = false;
109		private recoveryActive = false;
110		private readonly recoveryWaiters: Array<(release: () => void) => void> = [];
111		private resolveClose: (() => void) | undefined;
112		private readonly invalidators = new Set<() => void>();
113	
114		public onInvalidation(invalidator: () => void): void {
115			this.invalidators.add(invalidator);
116		}
117	
118		public attach(database: IDBDatabase): void {
119			if (this.closePromise !== undefined) {
120				database.close();
121				return;
122			}
123			if (this.connection !== undefined) throw new Error("IndexedDB lifecycle already attached");
124			this.connection = database;
125		}
126	
127		public startOperation(): IDBDatabase | undefined {
128			const database = this.connection;
129			if (database === undefined) return undefined;
130			this.activeOperations += 1;
131			return database;
132		}
133	
134		public isPoisoned(): boolean {
135			return this.poisoned;
136		}
137	
138		public isClosed(): boolean {
139			return this.connection === undefined;
140		}
141	
142		public acquireRecoveryTurn(): (() => void) | Promise<() => void> {
143			if (!this.recoveryActive) {
144				this.recoveryActive = true;
145				return () => this.releaseRecoveryTurn();
146			}
147			return new Promise((resolve) => this.recoveryWaiters.push(resolve));
148		}
149	
150		public latchPoison(reason: PersistedStorageError["reason"]): StoreResult<never> {
151			if (this.poisoned) return { ok: false, reason: "STORE_POISONED" };
152			this.poisoned = true;
153			return { ok: false, reason };
154		}
155	
156		public finishOperation(): void {
157			this.activeOperations -= 1;
158			this.resolveIfQuiescent();
159		}
160	
161		public close(): Promise<void> {
162			for (const invalidate of this.invalidators) invalidate();
163			this.closePromise ??= new Promise((resolve) => {
164				this.resolveClose = resolve;
165			});
166			const database = this.connection;
167			if (database !== undefined) {
168				this.connection = undefined;
169				database.close();
170			}
171			this.resolveIfQuiescent();
172			return this.closePromise;
173		}
174	
175		private resolveIfQuiescent(): void {
176			if (this.connection !== undefined || this.activeOperations !== 0) return;
177			const resolve = this.resolveClose;
178			this.resolveClose = undefined;
179			if (resolve !== undefined) queueMicrotask(resolve);
180		}
181	
182		private releaseRecoveryTurn(): void {
183			const next = this.recoveryWaiters.shift();
184			if (next === undefined) {
185				this.recoveryActive = false;
186				return;
187			}
188			next(() => this.releaseRecoveryTurn());
189		}
