223		public async probeBlobPresence(digests: readonly BlobDigest[]): Promise<StoreResult<readonly boolean[]>> {
224			const copied = copyPresenceDigests(digests);
225			if (copied === undefined) return { ok: false, reason: "INVALID_ARGUMENT" };
226			const database = this.lifecycle.startOperation();
227			if (database === undefined) return { ok: false, reason: "STORE_CLOSED" };
228			let transaction: IDBTransaction | undefined;
229			let completion: Promise<TransactionOutcome> | undefined;
230			try {
231				if (this.lifecycle.isPoisoned()) return { ok: false, reason: "STORE_POISONED" };
232				transaction = database.transaction(PHASE_2D_BLOBS_STORE, "readonly");
233				completion = transactionOutcome(transaction);
234				const store = transaction.objectStore(PHASE_2D_BLOBS_STORE);
235				const uniqueDigests: BlobDigest[] = [];
236				const uniqueIndex: Record<string, number> = Object.create(null) as Record<string, number>;
237				for (const digest of copied) {
238					if (uniqueIndex[digest] !== undefined) continue;
239					uniqueIndex[digest] = uniqueDigests.length;
240					uniqueDigests.push(digest);
241				}
242				const uniqueValues = await Promise.all(
243					uniqueDigests.map(async (digest) => (await this.request(store.getKey(digest))) !== undefined)
244				);
245				const values = copied.map((digest) => uniqueValues[uniqueIndex[digest] ?? -1] ?? false);
246				const outcome = await completion;
247				if (!outcome.ok) return substrateFailure(outcome.cause);
248				if (this.lifecycle.isPoisoned()) return { ok: false, reason: "STORE_POISONED" };
249				return { ok: true, value: Object.freeze(values) };
250			} catch (cause) {
251				if (transaction !== undefined) abortIfActive(transaction);
