322		private async run(command: unknown): Promise<StoreResult<unknown>> {
323			const prepared = prepareStorageAdapterCommand(command);
324			if (!prepared.ok) return prepared;
325			const database = this.lifecycle.startOperation();
326			if (database === undefined) {
327				return evaluateStorageAdapterCommand(prepared.value, [{ kind: "store-closed" }]).result;
328			}
329			try {
330				if (this.lifecycle.isPoisoned()) return { ok: false, reason: "STORE_POISONED" };
331				return await this.execute(database, prepared.value);
332			} finally {
333				this.lifecycle.finishOperation();
334			}
335		}
336	
337		private async execute(database: IDBDatabase, prepared: PreparedStorageAdapterCommand): Promise<StoreResult<unknown>> {
338			const operation = prepared.command.kind;
339			const mutation = isMutation(operation);
340			let transaction: IDBTransaction | undefined;
341			let completion: Promise<TransactionOutcome> | undefined;
342			try {
343				const objectId = "objectId" in prepared.command ? prepared.command.objectId : undefined;
344				let headObservation: TransactionHeadObservation | undefined;
345				const authorityStores =
346					mutation &&
347					objectId !== undefined &&
348					(operation === "completeGeneration" || operation === "swapHead" || this.recoveryCertificates.has(objectId));
349				transaction = mutation
350					? database.transaction(authorityStores ? allAuthorityStores() : [...OPERATION_STORES[operation]], "readwrite", {
351							durability: "strict",
352						})
353					: database.transaction([...OPERATION_STORES[operation]], "readonly");
354				completion = transactionOutcome(transaction);
355				if (mutation && transaction.durability !== "strict") throw new StrictDurabilityCapabilityError();
356				if (mutation) {
357					if (!("objectId" in prepared.command)) throw new Error("mutation command lacks object scope");
358					const observed = await this.observeHead(transaction, prepared.command.objectId);
359					if (!observed.ok) {
360						abortIfActive(transaction);
361						await completion;
362						return this.lifecycle.latchPoison(observed.reason);
363					}
364					headObservation = observed.value;
365					const recovered = await this.ensureCertificate(
366						transaction,
367						headObservation,
368						operation === "completeGeneration" || operation === "swapHead"
369					);
370					if (!recovered.ok) {
371						abortIfActive(transaction);
372						await completion;
373						return this.lifecycle.latchPoison(recovered.reason as PersistedStorageError["reason"]);
374					}
375				}
376	
377				const facts = await this.loadFacts(transaction, prepared, headObservation);
378				let evaluation = evaluateStorageAdapterCommand(prepared, facts);
379				if (prepared.command.kind === "completeGeneration" || prepared.command.kind === "swapHead") {
380					if (!evaluation.result.ok && evaluation.result.reason !== "INVALID_ARGUMENT") {
381						abortIfActive(transaction);
382						await completion;
383						return evaluation.result;
384					}
385					const authorization = await this.verifyCandidate(
386						transaction,
387						prepared.command.objectId,
388						prepared.command.generationId,
389						facts
390					);
391					if (authorization === undefined || !authorization.ok) {
392						abortIfActive(transaction);
393						await completion;
394						return authorization ?? { ok: false, reason: "INVALID_ARGUMENT" };
395					}
396					evaluation = evaluateStorageAdapterCommand(prepared, facts, authorization.value);
397				}
398				if (!evaluation.result.ok) {
399					abortIfActive(transaction);
400					await completion;
401					return evaluation.result;
402				}
403				if (mutation) await this.applyWrites(transaction, evaluation);
404				const outcome = await completion;
405				if (!outcome.ok) {
406					this.recoveryCertificates.clear();
407					return substrateFailure(outcome.cause);
408				}
409				if (operation === "swapHead" && evaluation.result.ok) {
410					const value = evaluation.result.value as Readonly<{ head: PresentHead }>;
411					this.recoveryCertificates.set(prepared.command.objectId, headFingerprint(value.head));
412				}
413				return evaluation.result;
414			} catch (cause) {
415				this.recoveryCertificates.clear();
416				const semanticResult =
417					cause instanceof PersistedStorageError
418						? this.lifecycle.latchPoison(cause.reason)
419						: cause instanceof PoisonedOperationError
420							? ({ ok: false, reason: "STORE_POISONED" } as const)
421							: undefined;
422				if (transaction !== undefined) abortIfActive(transaction);
423				if (completion !== undefined) await completion;
424				return semanticResult ?? substrateFailure(cause);
425			}
426		}
