428		private async loadFacts(
429			transaction: IDBTransaction,
430			prepared: PreparedStorageAdapterCommand,
431			headObservation?: TransactionHeadObservation
432		): Promise<readonly StorageAdapterFact[]> {
433			const facts: StorageAdapterFact[] = [];
434			const loadedBlobs = new Set<BlobDigest>();
435			const loadedPromotions = new Set<string>();
436			for (const requirement of prepared.requirements) {
437				switch (requirement.kind) {
438					case "head": {
439						const observed = headObservation ?? (await this.requiredHeadObservation(transaction, requirement.objectId));
440						if (observed.fact.objectId !== requirement.objectId)
441							throw new Error("transaction head observation has the wrong object scope");
442						facts.push(observed.fact);
443						break;
444					}
445					case "generation-page": {
446						const rows = await this.request(
447							transaction
448								.objectStore(PHASE_2D_GENERATIONS_STORE)
449								.getAll(
450									generationPageRange(requirement.objectId, requirement.afterGenerationId),
451									requirement.limitPlusOne
452								)
453						);
454						facts.push({
455							afterGenerationId: requirement.afterGenerationId,
456							generationRecords: rows.map((row) => boundGenerationRecord(row, requirement.objectId)),
457							kind: "generation-page",
458							objectId: requirement.objectId,
459						});
460						break;
461					}
462					case "generation":
463						await this.loadGeneration(transaction, requirement.objectId, requirement.generationId, facts);
464						break;
465					case "blob":
466						await this.loadBlob(transaction, requirement.digest, facts, loadedBlobs);
467						break;
468					case "promotion":
469						await this.loadPromotion(transaction, requirement, facts, loadedPromotions);
470						break;
471				}
472			}
473			if (prepared.command.kind === "swapHead") {
474				const headFact = facts.find(
475					(fact): fact is Extract<StorageAdapterFact, { kind: "head" }> => fact.kind === "head"
476				);
477				const decoded =
478					headFact?.headRecord === null || headFact === undefined ? undefined : decodeHeadRecordV1(headFact.headRecord);
479				if (
480					decoded?.ok === true &&
481					decoded.value.kind === "present" &&
482					decoded.value.generationId !== prepared.command.generationId
483				)
484					await this.loadGeneration(transaction, prepared.command.objectId, decoded.value.generationId, facts);
485			}
486			return facts;
487		}
