495		private async runRecovery(objectId: StorageObjectId): Promise<StoreResult<ActiveGenerationSnapshot>> {
496			const database = this.lifecycle.startOperation();
497			if (database === undefined) return { ok: false, reason: "STORE_CLOSED" };
498			const recoveryTurn = this.lifecycle.acquireRecoveryTurn();
499			const releaseRecoveryTurn = typeof recoveryTurn === "function" ? recoveryTurn : await recoveryTurn;
500			let transaction: IDBTransaction | undefined;
501			let completion: Promise<TransactionOutcome> | undefined;
502			try {
503				if (this.lifecycle.isClosed()) return { ok: false, reason: "STORE_CLOSED" };
504				if (this.lifecycle.isPoisoned()) return { ok: false, reason: "STORE_POISONED" };
505				transaction = database.transaction(allAuthorityStores(), "readwrite", { durability: "strict" });
506				completion = transactionOutcome(transaction);
507				if (transaction.durability !== "strict") throw new StrictDurabilityCapabilityError();
508				const result = await this.recoverWithinTransaction(transaction, objectId);
509				if (!result.ok) {
510					abortIfActive(transaction);
511					await completion;
512					return this.lifecycle.latchPoison(result.reason as PersistedStorageError["reason"]);
513				}
514				const outcome = await completion;
515				if (!outcome.ok) {
516					this.recoveryCertificates.clear();
517					return substrateFailure(outcome.cause);
518				}
519				const snapshot = freezeRecoverySnapshot(result.value);
520				this.recoveryCertificates.set(objectId, headFingerprint(snapshot.head));
521				return { ok: true, value: snapshot };
522			} catch (cause) {
523				if (transaction !== undefined) abortIfActive(transaction);
524				if (completion !== undefined) await completion;
525				if (cause instanceof PoisonedOperationError) return { ok: false, reason: "STORE_POISONED" };
526				this.recoveryCertificates.clear();
527				return substrateFailure(cause);
528			} finally {
529				releaseRecoveryTurn();
530				this.lifecycle.finishOperation();
531			}
532		}
