534		private async observeHead(
535			transaction: IDBTransaction,
536			objectId: StorageObjectId
537		): Promise<TransactionHeadObservationResult> {
538			const row = await this.request(transaction.objectStore(PHASE_2D_OBJECTS_STORE).get(objectId));
539			const classified = classifyPersistedState({
540				kind: "head",
541				objectId,
542				row: row === undefined ? null : { objectId: rowProperty(row, "objectId"), record: rowProperty(row, "record") },
543			});
544			if (!classified.ok) return classified;
545			if (classified.value.kind !== "head") throw new Error("persisted classifier returned the wrong fact kind");
546			return {
547				ok: true,
548				value: {
549					fact: { headRecord: classified.value.record, kind: "head", objectId },
550					head: classified.value.head,
551				},
552			};
553		}
