564		private async ensureCertificate(
565			transaction: IDBTransaction,
566			headObservation: TransactionHeadObservation,
567			required: boolean
568		): Promise<StoreResult<undefined>> {
569			const objectId = headObservation.fact.objectId;
570			if (this.recoveryCertificates.get(objectId) === headFingerprint(headObservation.head))
571				return { ok: true, value: undefined };
572			if (!required && !this.recoveryCertificates.has(objectId)) return { ok: true, value: undefined };
573			const recovered = await this.recoverWithinTransaction(transaction, objectId, headObservation);
574			if (!recovered.ok) return recovered;
575			this.recoveryCertificates.set(objectId, headFingerprint(recovered.value.head));
576			return { ok: true, value: undefined };
577		}
578	
579		private async recoverWithinTransaction(
580			transaction: IDBTransaction,
581			objectId: StorageObjectId,
582			headObservation?: TransactionHeadObservation
583		): Promise<StoreResult<ActiveGenerationSnapshot>> {
584			const observed: TransactionHeadObservationResult =
585				headObservation === undefined
586					? await this.observeHead(transaction, objectId)
587					: { ok: true, value: headObservation };
588			if (!observed.ok) return observed;
589			if (observed.value.fact.objectId !== objectId)
590				throw new Error("transaction head observation has the wrong object scope");
591			let after: GenerationId | null = null;
592			let adopted: GenerationRecord | null = null;
593			let count = 0;
594			let failure: "NON_CANONICAL_RECORD" | "UNSUPPORTED_STORAGE_SCHEMA" | undefined;
595			for (;;) {
596				const rows = await this.request(
597					transaction.objectStore(PHASE_2D_GENERATIONS_STORE).getAll(generationPageRange(objectId, after), 129)
598				);
599				for (const row of rows) {
600					const classified = classifyPersistedState({
601						kind: "generation",
602						objectId,
603						row: {
604							objectId: rowProperty(row, "objectId"),
605							generationId: rowProperty(row, "generationId"),
606							record: rowProperty(row, "record"),
607						},
608					});
609					if (!classified.ok)
610						failure =
611							failure === "UNSUPPORTED_STORAGE_SCHEMA" || classified.reason === "UNSUPPORTED_STORAGE_SCHEMA"
612								? "UNSUPPORTED_STORAGE_SCHEMA"
613								: "NON_CANONICAL_RECORD";
614					else if (classified.value.kind === "generation" && classified.value.generation.state === "Adopted") {
615						count++;
616						adopted ??= classified.value.generation;
617					}
618				}
619				if (rows.length < 129) break;
620				const last = rowProperty(rows.at(-1), "generationId");
621				if (typeof last !== "string") return { ok: false, reason: "NON_CANONICAL_RECORD" };
622				after = last as GenerationId;
623			}
624			if (failure !== undefined) return { ok: false, reason: failure };
625			const head = observed.value.head;
626			if (head.kind === "none")
627				return count === 0
628					? {
629							ok: true,
630							value: { kind: "empty", head, adoptedGeneration: null, recomputedClosureDigest: null, references: [] },
631						}
632					: { ok: false, reason: "NON_CANONICAL_RECORD" };
633			if (
634				count !== 1 ||
635				adopted === null ||
636				adopted.generationId !== head.generationId ||
637				adopted.closureDigest !== head.closureDigest
638			)
639				return { ok: false, reason: "NON_CANONICAL_RECORD" };
640			const verified = await this.verifyClosure(transaction, objectId, adopted, "adopted");
641			if (!verified.ok) return verified;
642			return {
643				ok: true,
644				value: {
645					kind: "active",
646					head: { ...head },
647					adoptedGeneration: {
648						...adopted,
649						baseExpectedHead: { ...adopted.baseExpectedHead },
650						closure: adopted.closure.map((r) => ({ ...r })),
651					},
652					recomputedClosureDigest: adopted.closureDigest,
653					references: adopted.closure.map((r) => ({ ...r })),
654				},
655			};
656		}
