658		private async loadGeneration(
659			transaction: IDBTransaction,
660			objectId: StorageObjectId,
661			generationId: GenerationId,
662			facts: StorageAdapterFact[]
663		): Promise<void> {
664			const row = await this.request(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).get([objectId, generationId]));
665			if (row === undefined) {
666				facts.push({ kind: "generation", objectId, generationId, generationRecord: null });
667				return;
668			}
669			const classified = classifyPersistedState({
670				kind: "generation",
671				objectId,
672				row: {
673					objectId: rowProperty(row, "objectId"),
674					generationId: rowProperty(row, "generationId"),
675					record: rowProperty(row, "record"),
676				},
677			});
678			if (!classified.ok) throw new PersistedStorageError(classified.reason);
679			if (classified.value.kind !== "generation") throw new Error("wrong classifier kind");
680			facts.push({ kind: "generation", objectId, generationId, generationRecord: classified.value.record });
