683		private async verifyCandidate(
684			transaction: IDBTransaction,
685			objectId: StorageObjectId,
686			generationId: GenerationId,
687			facts: readonly StorageAdapterFact[]
688		): Promise<StoreResult<unknown> | undefined> {
689			const fact = facts.find(
690				(value): value is Extract<StorageAdapterFact, { kind: "generation" }> =>
691					value.kind === "generation" && value.objectId === objectId && value.generationId === generationId
692			);
693			if (fact?.generationRecord === null || fact === undefined) return undefined;
694			const decoded = decodeGenerationRecordV1(fact.generationRecord);
695			if (!decoded.ok) return { ok: false, reason: "NON_CANONICAL_RECORD" };
696			return this.verifyClosure(transaction, objectId, decoded.value, "candidate");
697		}
698	
699		private verifyClosure(
700			transaction: IDBTransaction,
701			objectId: StorageObjectId,
702			generation: GenerationRecord,
703			mode: "adopted" | "candidate"
704		): Promise<StoreResult<unknown>> {
705			const session = storageAdapterClosureVerifier.start(generation, mode);
706			return new Promise((resolve, reject) => {
707				const advance = (): void => {
708					if (this.lifecycle.isPoisoned()) {
709						reject(new PoisonedOperationError());
710						return;
711					}
712					const verificationRequest = storageAdapterClosureVerifier.next(session);
713					if (verificationRequest === null) {
714						resolve(storageAdapterClosureVerifier.finish(session));
715						return;
716					}
717					const request =
718						verificationRequest.kind === "promotion"
719							? transaction
720									.objectStore(PHASE_2D_PROMOTIONS_STORE)
721									.get([objectId, generation.generationId, verificationRequest.reference.digest])
722							: transaction.objectStore(PHASE_2D_BLOBS_STORE).get(verificationRequest.reference.digest);
723					request.addEventListener(
724						"success",
725						() => {
726							if (verificationRequest.kind === "promotion")
727								storageAdapterClosureVerifier.acceptPromotion(session, request.result !== undefined);
728							else
729								storageAdapterClosureVerifier.acceptBlob(
730									session,
731									request.result === undefined ? null : rowProperty(request.result, "bytes")
732								);
733							advance();
734						},
735						{ once: true }
736					);
737					request.addEventListener("error", () => reject(request.error ?? new Error("IndexedDB request failed")), {
738						once: true,
739					});
740				};
741				advance();
742			});
743		}
