780		private async applyWrite(transaction: IDBTransaction, write: StorageAdapterWrite): Promise<void> {
781			switch (write.kind) {
782				case "replace-generation":
783					await requestValue(
784						transaction.objectStore(PHASE_2D_GENERATIONS_STORE).put({
785							generationId: write.generationId,
786							objectId: write.objectId,
787							record: new Uint8Array(write.record),
788						})
789					);
790					return;
791				case "replace-head":
792					await requestValue(
793						transaction.objectStore(PHASE_2D_OBJECTS_STORE).put({
794							objectId: write.objectId,
795							record: new Uint8Array(write.record),
796						})
797					);
798					return;
799				case "insert-blob":
800					await requestValue(
801						transaction.objectStore(PHASE_2D_BLOBS_STORE).add({
802							bytes: new Uint8Array(write.bytes),
803							digest: write.digest,
804						})
805					);
806					return;
807				case "insert-promotion":
808					await requestValue(
809						transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).add({
810							digest: write.digest,
811							generationId: write.generationId,
812							objectId: write.objectId,
813						})
814					);
815			}
816		}
817	}
818	
819	function isMutation(kind: StorageAdapterCommand["kind"]): kind is Phase2dMutationOperation {
820		return kind !== "readHead" && kind !== "readGenerationPage" && kind !== "getBlob";
821	}
822	
823	function allAuthorityStores(): string[] {
824		return [PHASE_2D_BLOBS_STORE, PHASE_2D_GENERATIONS_STORE, PHASE_2D_OBJECTS_STORE, PHASE_2D_PROMOTIONS_STORE];
825	}
826	
827	function commandWithKind(kind: StorageAdapterCommand["kind"], input: unknown): unknown {
828		if (typeof input !== "object" || input === null || Array.isArray(input)) return { kind, invalidInput: input };
829		const descriptors = Object.getOwnPropertyDescriptors(input);
830		if (Object.prototype.hasOwnProperty.call(descriptors, "kind")) return { kind, invalidInput: true };
831		const command = { kind } as Record<PropertyKey, unknown>;
832		Object.defineProperties(command, descriptors);
833		return command;
834	}
835	
836	function generationPrefix(objectId: StorageObjectId): IDBKeyRange {
837		return IDBKeyRange.bound([objectId], [objectId, []]);
838	}
839	
840	function generationPageRange(objectId: StorageObjectId, afterGenerationId: GenerationId | null): IDBKeyRange {
841		return afterGenerationId === null
842			? generationPrefix(objectId)
843			: IDBKeyRange.bound([objectId, afterGenerationId], [objectId, []], true, false);
844	}
845	
846	function rowProperty(value: unknown, key: string): unknown {
847		if (typeof value !== "object" || value === null) return undefined;
848		const descriptor = Object.getOwnPropertyDescriptor(value, key);
849		return descriptor !== undefined && "value" in descriptor ? descriptor.value : undefined;
850	}
851	
852	function copyPresenceDigests(value: unknown): readonly BlobDigest[] | undefined {
853		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype) return undefined;
854		const keys = Reflect.ownKeys(value);
855		if (keys.length !== value.length + 1 || !keys.includes("length")) return undefined;
856		const copied: BlobDigest[] = [];
857		for (let index = 0; index < value.length; index++) {
858			const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
859			if (descriptor === undefined || !descriptor.enumerable || !("value" in descriptor)) {
860				return undefined;
861			}
862			const parsed = typeof descriptor.value === "string" ? parseBlobDigest(descriptor.value) : undefined;
863			if (parsed?.ok !== true) return undefined;
864			copied.push(parsed.value);
865		}
866		return copied;
867	}
868	
869	function boundGenerationRecord(row: unknown, objectId: StorageObjectId): Uint8Array {
870		const classified = classifyPersistedState({
871			kind: "generation",
872			objectId,
873			row: {
874				generationId: rowProperty(row, "generationId"),
875				objectId: rowProperty(row, "objectId"),
876				record: rowProperty(row, "record"),
877			},
878		});
879		if (!classified.ok) throw new PersistedStorageError(classified.reason);
880		if (classified.value.kind !== "generation") throw new Error("persisted classifier returned the wrong fact kind");
881		return classified.value.record;
882	}
883	
884	function promotionKey(value: { objectId: StorageObjectId; generationId: GenerationId; digest: BlobDigest }): string {
885		return `${value.objectId}\0${value.generationId}\0${value.digest}`;
886	}
887	
888	function headFingerprint(head: ExpectedHead): string {
889		return head.kind === "none"
890			? `none\0${head.objectId}`
891			: `present\0${head.objectId}\0${head.generationId}\0${head.revision}\0${head.closureDigest}`;
892	}
893	
894	function requestValue<T>(request: IDBRequest<T>): Promise<T> {
895		return new Promise((resolve, reject) => {
896			request.addEventListener("success", () => resolve(request.result), { once: true });
897			request.addEventListener("error", () => reject(request.error ?? new Error("IndexedDB request failed")), {
898				once: true,
899			});
900		});
901	}
902	
903	function transactionOutcome(transaction: IDBTransaction): Promise<TransactionOutcome> {
904		return new Promise((resolve) => {
905			let observedError: unknown;
906			transaction.addEventListener("complete", () => resolve({ ok: true }), { once: true });
907			transaction.addEventListener(
908				"abort",
909				() =>
910					resolve({
911						cause: transaction.error ?? observedError ?? new Error("IndexedDB transaction aborted"),
912						ok: false,
913					}),
914				{ once: true }
915			);
916			transaction.addEventListener(
917				"error",
918				() => {
919					observedError ??= transaction.error ?? new Error("IndexedDB transaction failed");
920				},
921				{ once: true }
922			);
923		});
924	}
925	
926	function abortIfActive(transaction: IDBTransaction): void {
927		try {
928			transaction.abort();
929		} catch {
930			// The original semantic or substrate failure remains authoritative.
931		}
932	}
933	
934	function substrateFailure(cause: unknown): StoreResult<never> {
935		return { ok: false, reason: "SUBSTRATE_FAILURE", cause };
936	}
937	
938	function freezeRecoverySnapshot(snapshot: ActiveGenerationSnapshot): ActiveGenerationSnapshot {
939		if (snapshot.kind === "empty") {
940			return Object.freeze({
941				...snapshot,
942				head: Object.freeze({ ...snapshot.head }),
943				references: Object.freeze([] as []),
944			});
945		}
946		const adoptedGeneration = Object.freeze({
947			...snapshot.adoptedGeneration,
948			baseExpectedHead: Object.freeze({ ...snapshot.adoptedGeneration.baseExpectedHead }),
949			closure: Object.freeze(snapshot.adoptedGeneration.closure.map((reference) => Object.freeze({ ...reference }))),
950		});
951		return Object.freeze({
952			...snapshot,
953			head: Object.freeze({ ...snapshot.head }),
954			adoptedGeneration,
955			references: Object.freeze(snapshot.references.map((reference) => Object.freeze({ ...reference }))),
956		});
957	}
958	
959	/**
960	 * Creates the production IndexedDB durable store.
961	 * @param options - Isolated schema-owned database options.
962	 * @returns A strict durable-store adapter over one validated connection.
963	 */
964	export async function createBrowserAheDurableStore(
965		options: BrowserAheDurableStoreOptions
966	): Promise<BrowserAheDurableStore> {
967		const lifecycle = new IdbAdapterLifecycle();
968		const opaqueDatabase = await openPhase2dInternalDatabase(options, () => {
969			void lifecycle.close();
970		});
971		lifecycle.attach(opaqueDatabase as IDBDatabase);
972		const store = new IdbAheDurableStore(lifecycle);
973		registerBrowserAheReclamationMaintenance(store, lifecycle, options.databaseName);
974		return store;
975	}
