238	
239		private run(command: unknown): Promise<StoreResult<unknown>> {
240			const prepared = prepareStorageAdapterCommand(command);
241			if (!prepared.ok) return Promise.resolve(prepared);
242			if (this.closed) {
243				return Promise.resolve(evaluateStorageAdapterCommand(prepared.value, [{ kind: "store-closed" }]).result);
244			}
245			if (this.poisoned) return Promise.resolve({ ok: false, reason: "STORE_POISONED" });
246			return Promise.resolve(this.execute(prepared.value));
247		}
248	
249		private execute(prepared: PreparedStorageAdapterCommand): StoreResult<unknown> {
250			const operation = prepared.command.kind;
251			const mutation = isMutation(operation);
252			let transactionActive = false;
253			let result: StoreResult<unknown>;
254			try {
255				if (mutation) {
256					this.connection.exec("BEGIN IMMEDIATE");
257					transactionActive = true;
258					if (!("objectId" in prepared.command)) throw new Error("mutation command lacks object scope");
259					const recovered = this.ensureCertificate(
260						prepared.command.objectId,
261						operation === "completeGeneration" || operation === "swapHead"
262					);
263					if (!recovered.ok) {
264						this.poisoned = true;
265						this.connection.exec("ROLLBACK");
266						transactionActive = false;
267						return recovered;
268					}
269				}
270				const facts = this.loadFacts(prepared);
271				let evaluation = evaluateStorageAdapterCommand(prepared, facts);
272				if (prepared.command.kind === "completeGeneration" || prepared.command.kind === "swapHead") {
273					if (!evaluation.result.ok && evaluation.result.reason !== "INVALID_ARGUMENT") {
274						this.connection.exec("ROLLBACK");
275						transactionActive = false;
276						return evaluation.result;
277					}
278					const authorization = this.verifyCandidate(prepared.command.objectId, prepared.command.generationId, facts);
279					if (authorization === undefined || !authorization.ok) {
280						this.connection.exec("ROLLBACK");
281						transactionActive = false;
282						return authorization ?? { ok: false, reason: "INVALID_ARGUMENT" };
283					}
284					evaluation = evaluateStorageAdapterCommand(prepared, facts, authorization.value);
285				}
286				if (!evaluation.result.ok) {
287					if (transactionActive) {
288						this.connection.exec("ROLLBACK");
289						transactionActive = false;
290					}
291					return evaluation.result;
292				}
293				if (mutation) {
294					this.applyWrites(evaluation, operation);
295					if (this.crashObserver === undefined) {
296						if (operation === "beginGeneration") this.fault?.({ operation, edge: "before-commit" });
297					} else {
298						this.crashObserver({ operation, edge: "before-commit" });
299					}
300				}
301				if (transactionActive) {
302					this.connection.exec("COMMIT");
303					transactionActive = false;
304				}
305				result = evaluation.result;
306				if (mutation && operation === "swapHead" && result.ok) {
307					const swap = result.value as Readonly<{ head: PresentHead }>;
308					this.recoveryCertificates.set(prepared.command.objectId, headFingerprint(swap.head));
309				}
310			} catch (cause) {
311				this.recoveryCertificates.clear();
312				const persistedReason = cause instanceof PersistedStorageError ? cause.reason : undefined;
313				if (persistedReason !== undefined) this.poisoned = true;
314				if (transactionActive) {
315					try {
316						this.connection.exec("ROLLBACK");
317					} catch {
318						// The primary substrate failure remains the public cause.
319					}
320				}
321				return persistedReason === undefined
322					? { ok: false, reason: "SUBSTRATE_FAILURE", cause }
323					: { ok: false, reason: persistedReason };
324			}
325			if (mutation) this.crashObserver?.({ operation, edge: "after-commit" });
326			return result;
327		}
328	
329		private loadFacts(prepared: PreparedStorageAdapterCommand): readonly StorageAdapterFact[] {
330			const facts: StorageAdapterFact[] = [];
331			const loadedBlobs = new Set<BlobDigest>();
332			const loadedPromotions = new Set<string>();
333			for (const requirement of prepared.requirements) {
334				switch (requirement.kind) {
335					case "head": {
336						const row = this.connection
337							.prepare("SELECT head_record FROM objects WHERE object_id = ?")
338							.get(requirement.objectId) as DatabaseRow | undefined;
339						const classified = classifyPersistedState({
340							kind: "head",
341							objectId: requirement.objectId,
342							row: row === undefined ? null : { objectId: requirement.objectId, record: row.head_record },
343						});
344						if (!classified.ok) throw new PersistedStorageError(classified.reason);
345						if (classified.value.kind !== "head") throw new Error("persisted classifier returned the wrong fact kind");
346						facts.push({
347							headRecord: classified.value.record,
348							kind: "head",
349							objectId: requirement.objectId,
350						});
351						break;
352					}
353					case "generation-page": {
354						const rows = (
355							requirement.afterGenerationId === null
356								? this.connection
357										.prepare(
358											"SELECT generation_id, record FROM generations WHERE object_id = ? ORDER BY generation_id LIMIT ?"
359										)
360										.all(requirement.objectId, requirement.limitPlusOne)
361								: this.connection
362										.prepare(
363											"SELECT generation_id, record FROM generations WHERE object_id = ? AND generation_id > ? ORDER BY generation_id LIMIT ?"
364										)
365										.all(requirement.objectId, requirement.afterGenerationId, requirement.limitPlusOne)
366						) as DatabaseRow[];
367						facts.push({
368							afterGenerationId: requirement.afterGenerationId,
369							generationRecords: rows.map((row) => boundGenerationRecord(row, requirement.objectId)),
370							kind: "generation-page",
371							objectId: requirement.objectId,
372						});
373						break;
374					}
375					case "generation":
376						this.loadGeneration(requirement.objectId, requirement.generationId, facts);
377						break;
378					case "blob":
379						this.loadBlob(requirement.digest, facts, loadedBlobs);
380						break;
381					case "promotion":
382						this.loadPromotion(requirement, facts, loadedPromotions);
383						break;
384				}
385			}
386			if (prepared.command.kind === "swapHead") {
387				const headFact = facts.find(
388					(fact): fact is Extract<StorageAdapterFact, { kind: "head" }> => fact.kind === "head"
389				);
390				const decoded =
391					headFact?.headRecord === null || headFact === undefined ? undefined : decodeHeadRecordV1(headFact.headRecord);
392				if (
393					decoded?.ok === true &&
394					decoded.value.kind === "present" &&
395					decoded.value.generationId !== prepared.command.generationId
396				)
397					this.loadGeneration(prepared.command.objectId, decoded.value.generationId, facts);
398			}
399			return facts;
400		}
401		private loadGeneration(objectId: StorageObjectId, generationId: GenerationId, facts: StorageAdapterFact[]): void {
402			const row = this.connection
403				.prepare("SELECT record FROM generations WHERE object_id = ? AND generation_id = ?")
404				.get(objectId, generationId) as DatabaseRow | undefined;
405			if (row === undefined) {
406				facts.push({ kind: "generation", objectId, generationId, generationRecord: null });
407				return;
408			}
409			const classified = classifyPersistedState({
410				kind: "generation",
411				objectId,
412				row: { objectId, generationId, record: row.record },
413			});
414			if (!classified.ok) throw new PersistedStorageError(classified.reason);
415			if (classified.value.kind !== "generation") throw new Error("persisted classifier returned wrong kind");
416			facts.push({ kind: "generation", objectId, generationId, generationRecord: classified.value.record });
417		}
418	
419		private loadBlob(digest: BlobDigest, facts: StorageAdapterFact[], loaded: Set<BlobDigest>): void {
420			if (loaded.has(digest)) return;
421			const row = this.connection.prepare("SELECT bytes FROM blobs WHERE digest = ?").get(digest) as
422				| DatabaseRow
423				| undefined;
424			facts.push({ kind: "blob", digest, bytes: row === undefined ? null : databaseBytes(row.bytes) });
425			loaded.add(digest);
426		}
427	
428		private loadPromotion(
429			scope: Readonly<{ objectId: StorageObjectId; generationId: GenerationId; digest: BlobDigest }>,
430			facts: StorageAdapterFact[],
431			loaded: Set<string>
432		): void {
433			const key = `${scope.objectId}\0${scope.generationId}\0${scope.digest}`;
434			if (loaded.has(key)) return;
435			const row = this.connection
436				.prepare("SELECT 1 FROM promotions WHERE object_id = ? AND generation_id = ? AND digest = ?")
437				.get(scope.objectId, scope.generationId, scope.digest);
438			if (row !== undefined) facts.push({ kind: "promotion", ...scope });
439			loaded.add(key);
440		}
441	
442		private recoverTransaction(objectId: StorageObjectId): StoreResult<ActiveGenerationSnapshot> {
443			let active = false;
444			try {
445				this.connection.exec("BEGIN IMMEDIATE");
446				active = true;
447				const result = this.recoverWithinTransaction(objectId);
448				if (!result.ok) {
449					this.poisoned = true;
450					this.connection.exec("ROLLBACK");
451					active = false;
452					return result;
453				}
454				this.connection.exec("COMMIT");
455				active = false;
456				const snapshot = freezeRecoverySnapshot(result.value);
457				this.recoveryCertificates.set(objectId, headFingerprint(snapshot.head));
458				return { ok: true, value: snapshot };
459			} catch (cause) {
460				this.recoveryCertificates.clear();
461				if (active)
462					try {
463						this.connection.exec("ROLLBACK");
464					} catch {
465						/* preserve cause */
466					}
467				return { ok: false, reason: "SUBSTRATE_FAILURE", cause };
468			}
469		}
470	
471		private ensureCertificate(objectId: StorageObjectId, required: boolean): StoreResult<undefined> {
472			const head = this.readHeadWithinTransaction(objectId);
473			if (!head.ok) return head;
474			if (this.recoveryCertificates.get(objectId) === headFingerprint(head.value)) return { ok: true, value: undefined };
475			if (!required && !this.recoveryCertificates.has(objectId)) return { ok: true, value: undefined };
476			const recovered = this.recoverWithinTransaction(objectId);
477			if (!recovered.ok) return recovered;
478			this.recoveryCertificates.set(objectId, headFingerprint(recovered.value.head));
479			return { ok: true, value: undefined };
480		}
481	
482		private readHeadWithinTransaction(objectId: StorageObjectId): StoreResult<ExpectedHead> {
483			const row = this.connection.prepare("SELECT head_record FROM objects WHERE object_id = ?").get(objectId) as
484				| DatabaseRow
485				| undefined;
486			const classified = classifyPersistedState({
487				kind: "head",
488				objectId,
489				row: row === undefined ? null : { objectId, record: row.head_record },
490			});
491			return classified.ok && classified.value.kind === "head"
492				? { ok: true, value: classified.value.head }
493				: (classified as StoreResult<ExpectedHead>);
494		}
495	
496		private recoverWithinTransaction(objectId: StorageObjectId): StoreResult<ActiveGenerationSnapshot> {
497			const headResult = this.readHeadWithinTransaction(objectId);
498			if (!headResult.ok) return headResult;
499			let after: string | null = null;
500			let adopted: GenerationRecord | null = null;
501			let adoptedCount = 0;
502			let failure: "NON_CANONICAL_RECORD" | "UNSUPPORTED_STORAGE_SCHEMA" | undefined;
503			for (;;) {
504				const rows = (
505					after === null
506						? this.connection
507								.prepare(
508									"SELECT generation_id, record FROM generations WHERE object_id = ? ORDER BY generation_id LIMIT ?"
509								)
510								.all(objectId, 129)
511						: this.connection
512								.prepare(
513									"SELECT generation_id, record FROM generations WHERE object_id = ? AND generation_id > ? ORDER BY generation_id LIMIT ?"
514								)
515								.all(objectId, after, 129)
516				) as DatabaseRow[];
517				for (const row of rows) {
518					const classified = classifyPersistedState({
519						kind: "generation",
520						objectId,
521						row: { objectId, generationId: row.generation_id, record: row.record },
522					});
523					if (!classified.ok)
524						failure =
525							failure === "UNSUPPORTED_STORAGE_SCHEMA" || classified.reason === "UNSUPPORTED_STORAGE_SCHEMA"
526								? "UNSUPPORTED_STORAGE_SCHEMA"
527								: "NON_CANONICAL_RECORD";
528					else if (classified.value.kind === "generation" && classified.value.generation.state === "Adopted") {
529						adoptedCount++;
530						adopted ??= classified.value.generation;
531					}
532				}
533				if (rows.length < 129) break;
534				const cursor = rows.at(-1)?.generation_id;
535				if (typeof cursor !== "string") return { ok: false, reason: "NON_CANONICAL_RECORD" };
536				const parsedCursor = parseGenerationId(cursor);
537				if (!parsedCursor.ok) return { ok: false, reason: "NON_CANONICAL_RECORD" };
538				after = parsedCursor.value;
539			}
540			if (failure !== undefined) return { ok: false, reason: failure };
541			const head = headResult.value;
542			if (head.kind === "none")
543				return adoptedCount === 0
544					? {
545							ok: true,
546							value: { kind: "empty", head, adoptedGeneration: null, recomputedClosureDigest: null, references: [] },
547						}
548					: { ok: false, reason: "NON_CANONICAL_RECORD" };
549			if (
550				adoptedCount !== 1 ||
551				adopted === null ||
552				adopted.generationId !== head.generationId ||
553				adopted.closureDigest !== head.closureDigest
554			)
555				return { ok: false, reason: "NON_CANONICAL_RECORD" };
556			const verified = this.verifyClosure(objectId, adopted, "adopted");
557			if (!verified.ok) return verified;
558			return {
559				ok: true,
560				value: {
561					kind: "active",
562					head: { ...head },
563					adoptedGeneration: {
564						...adopted,
565						baseExpectedHead: { ...adopted.baseExpectedHead },
566						closure: adopted.closure.map((r) => ({ ...r })),
567					},
568					recomputedClosureDigest: adopted.closureDigest,
569					references: adopted.closure.map((r) => ({ ...r })),
570				},
571			};
572		}
573	
574		private verifyCandidate(
575			objectId: StorageObjectId,
576			generationId: GenerationId,
577			facts: readonly StorageAdapterFact[]
578		): StoreResult<unknown> | undefined {
579			const fact = facts.find(
580				(value): value is Extract<StorageAdapterFact, { kind: "generation" }> =>
581					value.kind === "generation" && value.objectId === objectId && value.generationId === generationId
582			);
583			if (fact?.generationRecord === null || fact === undefined) return undefined;
584			const decoded = decodeGenerationRecordV1(fact.generationRecord);
585			if (!decoded.ok) return { ok: false, reason: "NON_CANONICAL_RECORD" };
586			return this.verifyClosure(objectId, decoded.value, "candidate");
587		}
588	
589		private verifyClosure(
590			objectId: StorageObjectId,
591			generation: GenerationRecord,
592			mode: "adopted" | "candidate"
593		): StoreResult<unknown> {
594			const session = storageAdapterClosureVerifier.start(generation, mode);
595			for (
596				let request = storageAdapterClosureVerifier.next(session);
597				request !== null;
598				request = storageAdapterClosureVerifier.next(session)
599			) {
600				if (request.kind === "promotion") {
601					const present =
602						this.connection
603							.prepare("SELECT 1 FROM promotions WHERE object_id = ? AND generation_id = ? AND digest = ?")
604							.get(objectId, generation.generationId, request.reference.digest) !== undefined;
605					storageAdapterClosureVerifier.acceptPromotion(session, present);
606				} else {
607					const row = this.connection
608						.prepare("SELECT bytes FROM blobs WHERE digest = ?")
609						.get(request.reference.digest) as DatabaseRow | undefined;
610					storageAdapterClosureVerifier.acceptBlob(session, row === undefined ? null : row.bytes);
611				}
612			}
613			return storageAdapterClosureVerifier.finish(session);
614		}
615	
616		private applyWrites(evaluation: StorageAdapterEvaluation, operation: SqliteMutationOperation): void {
617			const occurrences = new Map<SqliteMutationStatement, number>();
618			const observe = (statement: SqliteMutationStatement): void => {
619				if (this.crashObserver === undefined) return;
620				const occurrence = (occurrences.get(statement) ?? 0) + 1;
621				occurrences.set(statement, occurrence);
622				this.crashObserver({ edge: "after-statement", occurrence, operation, statement });
623			};
624			for (const write of evaluation.writes) this.applyWrite(write, observe);
625		}
626	
627		private applyWrite(write: StorageAdapterWrite, observe: (statement: SqliteMutationStatement) => void): void {
628			switch (write.kind) {
629				case "replace-generation": {
630					const decoded = decodeGenerationRecordV1(write.record);
631					if (
632						!decoded.ok ||
633						decoded.value.objectId !== write.objectId ||
634						decoded.value.generationId !== write.generationId
635					) {
636						throw new Error("adapter emitted an invalid generation write");
637					}
638					this.connection
639						.prepare("INSERT OR IGNORE INTO objects(object_id, head_record) VALUES (?, NULL)")
640						.run(write.objectId);
641					observe("object-ensure");
642					const exists = this.connection
643						.prepare("SELECT 1 FROM generations WHERE object_id = ? AND generation_id = ?")
644						.get(write.objectId, write.generationId);
645					const statement =
646						exists === undefined
647							? this.connection.prepare("INSERT INTO generations(object_id, generation_id, record) VALUES (?, ?, ?)")
648							: this.connection.prepare("UPDATE generations SET record = ? WHERE object_id = ? AND generation_id = ?");
649					const result =
650						exists === undefined
651							? statement.run(write.objectId, write.generationId, new Uint8Array(write.record))
652							: statement.run(new Uint8Array(write.record), write.objectId, write.generationId);
653					observe(exists === undefined ? "generation-insert" : "generation-update");
654					requireOneChange(result.changes, "generation write");
655					return;
656				}
657				case "replace-head": {
658					const decoded = decodeHeadRecordV1(write.record);
659					if (!decoded.ok || decoded.value.kind !== "present" || decoded.value.objectId !== write.objectId) {
660						throw new Error("adapter emitted an invalid head write");
661					}
662					const result = this.connection
663						.prepare(
664							"INSERT INTO objects(object_id, head_record) VALUES (?, ?) " +
665								"ON CONFLICT(object_id) DO UPDATE SET head_record = excluded.head_record"
666						)
667						.run(write.objectId, new Uint8Array(write.record));
668					observe("head-upsert");
669					requireOneChange(result.changes, "head write");
670					return;
671				}
672				case "insert-blob": {
673					const result = this.connection
674						.prepare("INSERT INTO blobs(digest, bytes) VALUES (?, ?)")
675						.run(write.digest, new Uint8Array(write.bytes));
676					observe("blob-insert");
677					requireOneChange(result.changes, "blob insert");
678					return;
679				}
680				case "insert-promotion": {
681					const result = this.connection
682						.prepare("INSERT INTO promotions(object_id, generation_id, digest) VALUES (?, ?, ?)")
683						.run(write.objectId, write.generationId, write.digest);
684					observe("promotion-insert");
685					requireOneChange(result.changes, "promotion insert");
686				}
687			}
688		}
689	}
690	
691	function isMutation(kind: StorageAdapterCommand["kind"]): kind is SqliteMutationOperation {
692		return kind !== "readHead" && kind !== "readGenerationPage" && kind !== "getBlob";
693	}
694	
695	function headFingerprint(head: ExpectedHead): string {
696		return head.kind === "none"
697			? `none\0${head.objectId}`
698			: `present\0${head.objectId}\0${head.generationId}\0${head.revision}\0${head.closureDigest}`;
699	}
700	
701	function commandWithKind(kind: StorageAdapterCommand["kind"], input: unknown): unknown {
702		if (typeof input !== "object" || input === null || Array.isArray(input)) return { kind, invalidInput: input };
703		const descriptors = Object.getOwnPropertyDescriptors(input);
704		if (Object.prototype.hasOwnProperty.call(descriptors, "kind")) return { kind, invalidInput: true };
705		const command = { kind } as Record<PropertyKey, unknown>;
706		Object.defineProperties(command, descriptors);
707		return command;
708	}
709	
710	function databaseBytes(value: unknown): Uint8Array {
711		if (!(value instanceof Uint8Array)) throw new Error("SQLite returned a non-BLOB value");
712		return new Uint8Array(value);
713	}
714	
715	function boundGenerationRecord(row: DatabaseRow, objectId: StorageObjectId): Uint8Array {
716		const classified = classifyPersistedState({
717			kind: "generation",
718			objectId,
719			row: { generationId: row.generation_id, objectId, record: row.record },
720		});
721		if (!classified.ok) throw new PersistedStorageError(classified.reason);
722		if (classified.value.kind !== "generation") throw new Error("persisted classifier returned the wrong fact kind");
723		return classified.value.record;
724	}
725	
726	function requireOneChange(changes: number | bigint, label: string): void {
727		if (Number(changes) !== 1) throw new Error(`${label} did not affect exactly one row`);
728	}
729	
730	function hasExpectedPhysicalSchema(connection: DatabaseSync): boolean {
731		const tables = connection
732			.prepare("SELECT name FROM sqlite_schema WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
733			.all() as DatabaseRow[];
734		const expectedNames = Object.keys(EXPECTED_COLUMNS).sort();
735		if (tables.length !== expectedNames.length || tables.some((row, index) => row.name !== expectedNames[index])) {
736			return false;
737		}
738		for (const tableName of expectedNames as (keyof typeof EXPECTED_COLUMNS)[]) {
739			const columns = connection.prepare(`PRAGMA table_info("${tableName}")`).all() as DatabaseRow[];
740			const expectedColumns = EXPECTED_COLUMNS[tableName];
741			if (
742				columns.length !== expectedColumns.length ||
743				columns.some((column, index) => {
744					const expected = expectedColumns[index];
745					return (
746						expected === undefined ||
747						column.name !== expected.name ||
748						column.type !== expected.type ||
749						Number(column.notnull) !== expected.notnull ||
750						Number(column.pk) !== expected.pk ||
751						column.dflt_value !== null
752					);
753				})
754			) {
755				return false;
756			}
757			const foreignKeyColumns = (connection.prepare(`PRAGMA foreign_key_list("${tableName}")`).all() as DatabaseRow[])
758				.map((row) => `${String(row.table)}:${String(row.from)}:${String(row.to)}`)
759				.sort();
760			const expectedForeignKeyColumns = [...EXPECTED_FOREIGN_KEY_COLUMNS[tableName]].sort();
761			if (
762				foreignKeyColumns.length !== expectedForeignKeyColumns.length ||
763				foreignKeyColumns.some((value, index) => value !== expectedForeignKeyColumns[index])
764			) {
765				return false;
766			}
767		}
768		return true;
769	}
770	
771	function configureConnection(connection: DatabaseSync): void {
772		connection.exec("PRAGMA busy_timeout = 1000");
773		connection.exec("PRAGMA foreign_keys = ON");
774		const tableCount = (
775			connection
776				.prepare("SELECT count(*) AS count FROM sqlite_schema WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
777				.get() as DatabaseRow
778		).count;
779		if (Number(tableCount) === 0) {
780			connection.exec("BEGIN IMMEDIATE");
781			try {
782				connection.exec(SCHEMA);
783				if (!hasExpectedPhysicalSchema(connection)) throw new PersistedStorageError("UNSUPPORTED_STORAGE_SCHEMA");
784				connection.exec("COMMIT");
785			} catch (error) {
786				try {
787					connection.exec("ROLLBACK");
788				} catch {
789					// Preserve the primary schema-creation failure.
790				}
791				throw error;
792			}
793		}
794		if (!hasExpectedPhysicalSchema(connection)) throw new PersistedStorageError("UNSUPPORTED_STORAGE_SCHEMA");
795		connection.exec("PRAGMA journal_mode = WAL");
796		connection.exec("PRAGMA synchronous = FULL");
797	}
798	
799	function freezeRecoverySnapshot(snapshot: ActiveGenerationSnapshot): ActiveGenerationSnapshot {
800		if (snapshot.kind === "empty")
801			return Object.freeze({
802				...snapshot,
803				head: Object.freeze({ ...snapshot.head }),
804				references: Object.freeze([] as []),
805			});
806		return Object.freeze({
807			...snapshot,
808			head: Object.freeze({ ...snapshot.head }),
809			adoptedGeneration: Object.freeze({
810				...snapshot.adoptedGeneration,
811				baseExpectedHead: Object.freeze({ ...snapshot.adoptedGeneration.baseExpectedHead }),
812				closure: Object.freeze(snapshot.adoptedGeneration.closure.map((reference) => Object.freeze({ ...reference }))),
813			}),
814			references: Object.freeze(snapshot.references.map((reference) => Object.freeze({ ...reference }))),
815		});
816	}
817	
818	/**
819	 * Creates the production SQLite store.
820	 * @param options - File-backed SQLite options.
821	 * @param fault - Optional bounded test-only fault callback.
822	 * @returns A strict store over one configured connection.
823	 * @internal
824	 */
825	export function createSqliteScaffold(
826		options: SqliteAheDurableStoreOptions,
827		fault?: SqliteMutationFault
828	): AheDurableStore {
829		return createInstrumentedSqliteScaffold(options, fault).store;
830	}
831	
832	/**
833	 * Creates the store and exact live-connection probes used by the package-local RED.
834	 * @param options - File-backed SQLite options.
835	 * @param fault - Optional bounded test-only fault callback.
836	 * @param crashObserver - Optional expanded process-death checkpoint observer.
837	 * @returns Store and non-exported connection instrumentation.
838	 * @internal
839	 */
840	export function createInstrumentedSqliteScaffold(
841		options: SqliteAheDurableStoreOptions,
842		fault?: SqliteMutationFault,
843		crashObserver?: SqliteCrashCheckpointObserver
844	): SqliteScaffoldInstrumentation {
845		const connection = new DatabaseSync(options.filename);
846		try {
847			configureConnection(connection);
848		} catch (error) {
849			connection.close();
850			throw error;
851		}
852		return {
853			attemptInvalidForeignKeyInsert: (): void => {
854				connection.exec(
855					"CREATE TEMP TABLE phase_2c_parent(id INTEGER PRIMARY KEY);" +
856						"CREATE TEMP TABLE phase_2c_child(parent_id INTEGER REFERENCES phase_2c_parent(id));"
857				);
858				try {
859					connection.prepare("INSERT INTO phase_2c_child(parent_id) VALUES (?)").run(1);
860				} finally {
861					connection.exec("DROP TABLE phase_2c_child;DROP TABLE phase_2c_parent;");
862				}
863			},
864			readPragma: (pragma): unknown => {
865				const row = connection.prepare(`PRAGMA ${pragma}`).get();
866				return row === undefined ? undefined : Object.values(row)[0];
867			},
868			store: new SqliteAheDurableStore(connection, fault, crashObserver),
869		};
870	}
