3	import {
4		assertDurableIssueScope,
5		copyDurableIssueScope,
6		DurableIssuanceInvalidArgumentError,
7		isClosedDurableIssuanceRecord,
8		isValidDurableAuthorSequence,
9	} from "./contract.js";
10	import type { DurableIssuanceError, DurableIssuanceStore, DurableIssueScope, DurableLineage } from "./types.js";
11	
12	const HEX_DIGEST = /^[0-9a-f]{64}$/u;
13	
14	export interface DurableIssuancePruningState {
15		readonly lineage: DurableLineage;
16		readonly prunedThroughAuthorSequence: number | null;
17		readonly scope: DurableIssueScope;
18	}
19	
20	export interface DurableIssuancePruningInput {
21		readonly closedEpoch: number;
22		readonly commitQcRef: Readonly<{ readonly byteLength: number; readonly digest: string }>;
23		readonly expectedLineage: DurableLineage;
24		readonly expectedPrunedThroughAuthorSequence: number | null;
25		readonly scope: DurableIssueScope;
26		readonly snapshotManifestDigest: string;
27		readonly throughAuthorSequence: number;
28	}
29	
30	export interface DurableIssuancePruningReceipt {
31		readonly closedEpoch: number;
32		readonly commitQcRef: Readonly<{ readonly byteLength: number; readonly digest: string }>;
33		readonly deletedAuthorSequenceRange: Readonly<{ readonly from: number; readonly through: number }> | null;
34		readonly observedLineage: DurableLineage;
35		readonly prunedThroughAuthorSequence: number;
36		readonly scope: DurableIssueScope;
37		readonly snapshotManifestDigest: string;
38	}
39	
40	export interface DurableIssuancePruningMaintenance {
41		inspectPruningState(scope: DurableIssueScope): Promise<DurableIssuancePruningState>;
42		pruneAuthenticatedSettledPrefix(input: unknown): Promise<DurableIssuancePruningReceipt>;
43		prunePublishedPrefix(input: unknown): Promise<DurableIssuancePruningReceipt>;
44	}
